import { ChangeDetectionStrategy, Component, input } from '@angular/core';

@Component({
  selector: 'aevko-marker',
  standalone: true,
  template: '<span class="dot" aria-hidden="true"></span><ng-content />',
  styleUrl: './marker.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'marker', '[attr.data-variant]': 'variant()' },
})
export class AevkoMarker {
  readonly variant = input<'default' | 'muted' | 'danger'>('default');
}

:host {
  align-items: center;
  display: inline-flex;
  font: 600 0.8rem/1 var(--aevko-font-sans, sans-serif);
  gap: 0.4rem;
}
.dot {
  background: var(--aevko-foreground, #09090b);
  height: 0.5rem;
  width: 0.5rem;
}
:host([data-variant='muted']) .dot {
  background: var(--aevko-muted, #71717a);
}
:host([data-variant='danger']) .dot {
  background: var(--aevko-danger, #3f3f3f);
}
